SELECT "TESTAPP_CONTACT"."ID", "TESTAPP_CONTACT"."COMPANY", "TESTAPP_CONTACT"."ACCOUNT_NUMBER" FROM "TESTAPP_CONTACT" WHERE ((("TESTAPP_CONTACT"."COMPANY", "TESTAPP_CONTACT"."ACCOUNT_NUMBER") IN (SELECT U0."COMPANY" AS "COMPANY", U0."NUMBER" AS "NUMBER" FROM "TESTAPP_ACCOUNT" U0 WHERE U0."NUMBER" > %s) OR "TESTAPP_CONTACT"."COMPANY" = %s) AND CAST(%s AS INTEGER) = (CASE WHEN (CASE WHEN (SELECT 1 FROM LATERAL (SELECT U0."COMPANY" AS "COMPANY", U0."NUMBER" AS "NUMBER" FROM "TESTAPP_ACCOUNT" U0 WHERE U0."NUMBER" > %s) AS "DJDB2I_IN" (V1, V2) WHERE "DJDB2I_IN".V1 = "TESTAPP_CONTACT"."COMPANY" AND "DJDB2I_IN".V2 = "TESTAPP_CONTACT"."ACCOUNT_NUMBER" FETCH FIRST 1 ROWS ONLY) IS NOT NULL THEN TRUE WHEN (SELECT 1 FROM LATERAL (SELECT U0."COMPANY" AS "COMPANY", U0."NUMBER" AS "NUMBER" FROM "TESTAPP_ACCOUNT" U0 WHERE U0."NUMBER" > %s) AS "DJDB2I_IN" (V1, V2) WHERE ("DJDB2I_IN".V1 = "TESTAPP_CONTACT"."COMPANY" OR "DJDB2I_IN".V1 IS NULL OR "TESTAPP_CONTACT"."COMPANY" IS NULL) AND ("DJDB2I_IN".V2 = "TESTAPP_CONTACT"."ACCOUNT_NUMBER" OR "DJDB2I_IN".V2 IS NULL OR "TESTAPP_CONTACT"."ACCOUNT_NUMBER" IS NULL) FETCH FIRST 1 ROWS ONLY) IS NOT NULL THEN NULL ELSE FALSE END) = TRUE THEN CAST(%s AS INTEGER) ELSE CAST(%s AS INTEGER) END + CASE WHEN "TESTAPP_CONTACT"."COMPANY" = %s THEN CAST(%s AS INTEGER) ELSE CAST(%s AS INTEGER) END));
